from rb_lib import P, SP, C, M, q, X

UJI = '''
def jalankan(*tes):
    lulus = 0
    for t in tes:
        try:
            t()
            print('LULUS', t.__name__)
            lulus += 1
        except AssertionError as e:
            print('GAGAL', t.__name__, '-', e)
    print(f'{lulus}/{len(tes)} tes lulus')
'''

