M('Teknik desain test case', 'Pemula',
  'Equivalence partitioning, boundary value analysis, decision table, dan state transition, lengkap dengan tes yang bisa dijalankan.',
  ['Test Case Design', 'Equivalence Partitioning', 'Boundary Value Analysis', 'Decision Table', 'State Transition'], [
  P('Equivalence partitioning dan boundary value',
    ['Kita tidak mungkin menguji semua input. <b>Equivalence partitioning</b> membagi input menjadi kelompok yang seharusnya diperlakukan sama, lalu cukup menguji satu wakil per kelompok. Contoh: umur pendaftar BPJS mandiri anak 0 sampai 17, dewasa 18 sampai 59, lansia 60 ke atas, dan kelompok tidak valid (negatif).',
     '<b>Boundary value analysis</b> menguji tepat di batas karena bug sering muncul di sana (salah tulis <code>&lt;</code> dan <code>&lt;=</code>). Untuk batas 18, uji 17, 18, dan 19. Gabungan keduanya menghasilkan sedikit tes tetapi efektif.',
     'Di bawah ini fungsi kategori umur dengan bug yang disengaja. Jalankan tesnya dan lihat tes batas mana yang menangkap bug itu.'],
    UJI + "\ndef kategori(umur):\n    if umur < 0:\n        return 'tidak valid'\n    if umur < 18:\n        return 'anak'\n    if umur < 61:        # BUG: seharusnya < 60\n        return 'dewasa'\n    return 'lansia'\n\ndef tes_partisi():\n    assert kategori(10) == 'anak'\n    assert kategori(30) == 'dewasa'\n    assert kategori(75) == 'lansia'\n    assert kategori(-1) == 'tidak valid'\n\ndef tes_batas_18():\n    assert [kategori(u) for u in (17, 18, 19)] == ['anak', 'dewasa', 'dewasa']\n\ndef tes_batas_60():\n    hasil = kategori(60)\n    assert hasil == 'lansia', f'umur 60 menjadi {hasil!r}'\n\njalankan(tes_partisi, tes_batas_18, tes_batas_60)",
    pts=['Satu wakil per kelompok input.', 'Uji tepat di batas: batas - 1, batas, batas + 1.', 'Tes partisi saja tidak menangkap bug batas.'],
    qs=[q('Untuk aturan "diskon jika belanja minimal Rp100.000", nilai batas yang diuji?', ['99.999, 100.000, 100.001', '50.000 dan 150.000', 'Hanya 100.000'], 0, 'Batas dan tetangganya.')],
    so=[SP('Kata sandi valid jika panjangnya 8 sampai 20 karakter. Tulis daftar panjang yang diuji dengan boundary value analysis dan cetak hasil validasinya.', 'Uji 7, 8, 9, 19, 20, 21.',
           "def valid(pw):\n    return 8 <= len(pw) <= 20\nfor n in [7, 8, 9, 19, 20, 21]:\n    print(n, valid('a' * n))")]),
  P('Decision table',
    ['<b>Decision table</b> dipakai jika hasil bergantung pada <b>kombinasi beberapa kondisi</b>. Tulis semua kondisi sebagai baris, setiap kolom adalah satu kombinasi, lalu tentukan aksinya. Dengan n kondisi ya/tidak ada 2ⁿ kombinasi.',
     'Contoh aturan ongkir toko online: gratis ongkir jika pelanggan member <b>dan</b> belanja minimal Rp150.000; jika hanya salah satu terpenuhi, diskon ongkir 50%; jika tidak keduanya, ongkir penuh.',
     'Tabel membuat kombinasi yang terlupa langsung terlihat, dan setiap kolom menjadi satu test case.'],
    UJI + "\ndef ongkir(member, belanja, tarif=20000):\n    if member and belanja >= 150000:\n        return 0\n    if member or belanja >= 150000:\n        return tarif // 2\n    return tarif\n\ntabel = [\n    # member, belanja, harapan\n    (True,  200000, 0),\n    (True,  100000, 10000),\n    (False, 200000, 10000),\n    (False, 100000, 20000),\n]\n\ndef tes_tabel_keputusan():\n    for member, belanja, harap in tabel:\n        hasil = ongkir(member, belanja)\n        assert hasil == harap, f'{member}, {belanja}: {hasil} != {harap}'\n\njalankan(tes_tabel_keputusan)",
    tb=[{'c': 'Decision table ongkir', 'h': ['Kondisi / aksi', 'K1', 'K2', 'K3', 'K4'], 'r': [
      ['Member?', 'Ya', 'Ya', 'Tidak', 'Tidak'], ['Belanja ≥ 150 rb?', 'Ya', 'Tidak', 'Ya', 'Tidak'], ['Ongkir', 'Gratis', '50%', '50%', 'Penuh']]}],
    pts=['Untuk kombinasi beberapa kondisi.', '2 kondisi ya/tidak = 4 kolom.', 'Setiap kolom menjadi satu test case.'],
    qs=[q('Berapa kombinasi untuk 3 kondisi ya/tidak?', ['8', '6', '3'], 0, '2³.')],
    so=[SP('Buat decision table untuk login: email terdaftar (ya/tidak) dan kata sandi benar (ya/tidak). Cetak setiap kombinasi beserta pesan yang tepat.', 'Empat kombinasi; jangan beri tahu apakah email terdaftar demi keamanan.',
           "for terdaftar in (True, False):\n    for benar in (True, False):\n        if terdaftar and benar:\n            pesan = 'Masuk ke Beranda'\n        else:\n            pesan = 'Email atau kata sandi salah'\n        print(terdaftar, benar, '->', pesan)")]),
  P('State transition testing',
    ['Beberapa fitur punya <b>keadaan (state)</b> yang berubah karena peristiwa. Contoh: status pesanan (Dibuat → Dibayar → Dikirim → Selesai, atau Dibatalkan). <b>State transition testing</b> memeriksa bahwa transisi yang sah berhasil dan transisi yang <b>tidak sah ditolak</b>.',
     'Gambar diagram state, lalu buat tabel: keadaan sekarang, peristiwa, keadaan berikutnya. Tes negatif sama pentingnya, misalnya pesanan yang sudah Dikirim tidak boleh dibatalkan begitu saja.',
     'Teknik ini juga cocok untuk penguncian akun (salah sandi 5 kali), alur onboarding, dan mesin ATM.'],
    UJI + "\nTRANSISI = {\n    ('dibuat', 'bayar'): 'dibayar',\n    ('dibuat', 'batal'): 'dibatalkan',\n    ('dibayar', 'kirim'): 'dikirim',\n    ('dibayar', 'batal'): 'dibatalkan',\n    ('dikirim', 'terima'): 'selesai',\n}\n\ndef ubah(status, peristiwa):\n    if (status, peristiwa) not in TRANSISI:\n        raise ValueError(f'{peristiwa} tidak boleh saat {status}')\n    return TRANSISI[(status, peristiwa)]\n\ndef tes_alur_normal():\n    s = 'dibuat'\n    for p in ['bayar', 'kirim', 'terima']:\n        s = ubah(s, p)\n    assert s == 'selesai'\n\ndef tes_tidak_boleh_batal_setelah_kirim():\n    try:\n        ubah('dikirim', 'batal')\n        assert False, 'seharusnya ditolak'\n    except ValueError:\n        pass\n\njalankan(tes_alur_normal, tes_tidak_boleh_batal_setelah_kirim)",
    pts=['Uji transisi sah dan tidak sah.', 'Tabel: state, peristiwa, state berikutnya.', 'Cocok untuk status pesanan, penguncian akun, ATM.'],
    qs=[q('Tes negatif yang tepat untuk status pesanan?', ['Mengirim pesanan yang belum dibayar', 'Membayar pesanan baru', 'Menerima pesanan yang dikirim'], 0, 'Transisi tidak sah harus ditolak.')],
    so=[SP('Simulasikan penguncian akun: setelah 3 kali salah sandi berturut-turut, status menjadi "terkunci". Cetak status setelah urutan percobaan salah, salah, benar, salah, salah, salah.', 'Reset penghitung saat benar.',
           "status, salah = 'aktif', 0\nfor benar in [False, False, True, False, False, False]:\n    if status == 'terkunci':\n        break\n    if benar:\n        salah = 0\n    else:\n        salah += 1\n        if salah == 3:\n            status = 'terkunci'\n    print(benar, salah, status)")]),
]),

